/*
 * Single source of visual values; screens use generated utilities only. See
 * web/registry/rules/foundations.md and src/theme/tokens.test.ts for usage and contrast checks.
 */
@theme {
  /*
   * Clear Tailwind scales so only declared tokens generate utilities; ESLint rejects out-of-scale
   * classes. This also removes tw-animate-css animations, so use only those declared below.
   */
  --color-*: initial;
  --text-*: initial;
  --font-weight-*: initial;
  --spacing: initial;
  --spacing-*: initial;
  --radius-*: initial;
  --shadow-*: initial;
  --drop-shadow-*: initial;
  --animate-*: initial;

  --color-navbar: #000000;
  --color-background: #111111;
  --color-foreground: #f2f2f2;
  --color-muted: #191919;
  --color-muted-foreground: #b3b3b3;
  --color-card: #212121;
  --color-card-foreground: #f2f2f2;
  --color-popover: #2b2b2b;
  --color-popover-foreground: #f2f2f2;

  --color-secondary: #363636;
  --color-secondary-foreground: #f2f2f2;
  --color-accent: #363636;
  --color-accent-foreground: #f2f2f2;

  /*
   * Primary cyan is for one primary action per section, selection and progress; use the darker
   * variant for pressed states.
   */
  --color-primary: #3ec1d3;
  --color-primary-hover: #68cedc;
  --color-primary-active: #29a4b5;
  --color-primary-foreground: #111111;
  --color-primary-soft: #163b40;

  --color-border: #383838;
  --color-input: #7a7a7a;
  --color-ring: #68cedc;

  /* Always accompany status colors with text and an icon. */
  --color-destructive: #ff8a80;
  --color-destructive-strong: #b8363c;
  --color-destructive-foreground: #ffffff;
  --color-destructive-soft: #4b2023;
  --color-warning: #f5b452;
  --color-warning-foreground: #111111;
  --color-warning-soft: #4c3520;
  --color-success: #5fd39a;
  --color-success-foreground: #111111;
  --color-success-soft: #204334;

  --color-favorite: #ff6f9c;

  /* The only translucent color, for backdrops and thumbnail overlays. */
  --color-overlay: rgb(0 0 0 / 0.88);

  --font-sans:
    "Inter Variable", "Noto Sans JP Variable", system-ui, -apple-system, "Segoe UI",
    "Hiragino Sans", sans-serif;
  --text-2xs: 0.6875rem;
  --text-2xs--line-height: 1rem;
  --text-xs: 0.75rem;
  --text-xs--line-height: 1rem;
  --text-sm: 0.875rem;
  --text-sm--line-height: 1.25rem;
  --text-base: 1rem;
  --text-base--line-height: 1.5rem;
  --text-lg: 1.125rem;
  --text-lg--line-height: 1.75rem;
  --text-xl: 1.25rem;
  --text-xl--line-height: 1.75rem;
  /* Fit Duplicates within a 56px rail item. */
  --text-rail: 0.625rem;
  --text-rail--line-height: 1;
  --text-video-title: 1.5rem;
  --text-video-title--line-height: 1.375;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  --spacing-0: 0px;
  --spacing-0\.5: 0.125rem;
  --spacing-1: 0.25rem;
  --spacing-1\.5: 0.375rem;
  --spacing-2: 0.5rem;
  --spacing-3: 0.75rem;
  --spacing-4: 1rem;
  --spacing-5: 1.25rem;
  --spacing-6: 1.5rem;
  --spacing-8: 2rem;
  --spacing-9: 2.25rem;
  --spacing-10: 2.5rem;
  --spacing-12: 3rem;
  --spacing-16: 4rem;
  --spacing-navbar: 3.25rem;
  --spacing-sidebar: 14.5rem;
  --spacing-sidebar-rail: 4.25rem;
  --spacing-rail-item: 3.5rem;
  --spacing-card-0: 13.75rem;
  --spacing-card-1: 17.5rem;
  --spacing-card-2: 22.5rem;
  --spacing-card-3: 30rem;
  --spacing-list-thumb-cell: 8rem;
  --spacing-list-thumb: 7rem;
  --spacing-list-number: 5rem;
  --spacing-list-number-wide: 6rem;
  --spacing-list-date: 7rem;
  --spacing-history-thumb: 12rem;
  --spacing-history-thumb-sm: 8rem;
  --spacing-search-min: 5rem;
  --spacing-search-min-sm: 10rem;
  --spacing-zoom: 6rem;
  /* Reserve list-end space so the selection bar cannot cover the final cards. */
  --spacing-selection-bar: 2.75rem;
  --spacing-selection-bar-clearance: 6rem;
  --spacing-popover: 18rem;
  --spacing-popover-wide: 20rem;
  /* Leave 0.75rem on each viewport edge for fixed notifications. */
  --spacing-viewport-inset: calc(100vw - 1.5rem);
  --spacing-chip-label: 12rem;
  --spacing-combobox: 10rem;
  --spacing-combobox-list: 16rem;
  --spacing-combobox-panel: 15rem;
  --spacing-combobox-panel-max: 40vh;
  --spacing-menu: 11rem;
  /* Detail aside width includes a 224px card plus horizontal padding; wider from xl. */
  --spacing-detail-aside: 16rem;
  --spacing-detail-aside-wide: 16rem;
  --spacing-editor-aside: 20rem;
  --spacing-editor-aside-wide: 24rem;
  /* Narrow-screen editor stage occupies roughly 45% of viewport height. */
  --spacing-editor-stage: 45dvh;
  --spacing-form-page-aside: 16.25rem;
  /* Cap sticky list-aside height beneath the top bar and scroll overflow internally. */
  --spacing-list-aside: 11rem;
  --spacing-list-aside-max: calc(100dvh - 3.25rem - 2rem);
  /* Fit Video conversion with text-sm and px-2 on one line. */
  --spacing-settings-nav: 10rem;
  --spacing-settings-nav-max: calc(100dvh - 3.25rem - 2rem);
  --spacing-related-thumb: 10rem;
  --spacing-neighbor-arrow: 1.75rem;
  --spacing-neighbor-arrow-min: 4.5rem;
  --spacing-neighbor-arrow-min-sm: 6rem;
  --spacing-control-bar-clearance: 3.5rem;
  --spacing-versions-popover: min(28rem, calc(100vw - 2rem));
  /*
   * Show two playlist cards and the next card's top; cap at roughly half short viewports so lower
   * lists remain reachable.
   */
  --spacing-playlist-panel: min(28rem, 45dvh);
  --spacing-visibility-x: 0.625rem;
  --spacing-technical-x: 0.625rem;
  --spacing-issue-list: 50vh;
  --spacing-folder-list: 18rem;
  /* Bound run output so facts and actions remain visible at both 1280x800 and 360x640. */
  --spacing-run-output: 40vh;
  --spacing-activity-card: 3.25rem;
  --spacing-activity-time: 6.5rem;
  --spacing-activity-bar: 10rem;

  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;

  /* Reserve shadows for hovered cards, overlays and image marks, not resting surfaces. */
  --shadow-card-hover: 0 0 0 1px rgb(255 255 255 / 0.1), 0 8px 24px rgb(0 0 0 / 0.45);
  --shadow-elevated: 0 0 0 1px rgb(255 255 255 / 0.06), 0 12px 32px rgb(0 0 0 / 0.55);
  /* Use a shadow for sticky table-header borders because row borders do not stick with them. */
  --shadow-table-head: inset 0 -1px 0 var(--color-border);
  --drop-shadow-mark: 0 1px 2px rgb(0 0 0 / 0.75);

  /* Disable these animations under reduced-motion preferences. */
  --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);
  --animate-fade-in: fade-in 150ms var(--ease-out-quart);
  --animate-pop-in: pop-in 120ms var(--ease-out-quart);
  --animate-slide-up: slide-up 200ms var(--ease-out-quart);
  --animate-shimmer: shimmer 1.6s linear infinite;
  --animate-spin: spin 1s linear infinite;
  --animate-pulse: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;

  --size-seek-preview: clamp(160px, calc(89.41px + 19.61vw), 240px);
  --size-seek-preview-max: 240px;
  --spacing-seek-preview-gap: 18px;
  --spacing-seek-preview-unavailable-gap: 40px;
  --spacing-seek-preview-edge: 4px;
  --spacing-seek-preview-time-y: 2px;
  --spacing-seek-preview-time-x: 6px;
  --text-seek-preview: 11px;
  --duration-seek-preview: 100ms;
  /* Chapter tick width; see docs/design-docs/media-information.md. */
  --spacing-chapter-mark: 2px;

  @keyframes fade-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes pop-in {
    from {
      opacity: 0;
      transform: scale(0.97);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }
  @keyframes slide-up {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
  @keyframes spin {
    to {
      transform: rotate(360deg);
    }
  }
  @keyframes pulse {
    50% {
      opacity: 0.5;
    }
  }
  @keyframes shimmer {
    from {
      background-position: -200% 0;
    }
    to {
      background-position: 200% 0;
    }
  }
}

/*
 * Reserve height for headings and metadata, then cap player width by aspect, native width and
 * 100rem. Inline utilities must read element-local --vv-video-aspect and --vv-video-width rather
 * than root-resolved variables.
 */
@theme inline {
  --spacing-player-height: calc(100dvh - 12.25rem);
  --spacing-player-height-lg: max(100dvh - 8.25rem, 15rem);
  --spacing-player-width: calc((100dvh - 12.25rem) * max(var(--vv-video-aspect), 16 / 9));
  --spacing-player-width-lg: min(
    calc(max(100dvh - 8.25rem, 15rem) * max(var(--vv-video-aspect), 16 / 9)),
    100rem,
    max(60rem, var(--vv-video-width, 100rem))
  );
  --aspect-player: var(--vv-video-aspect);
}

@utility bg-shimmer {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-secondary) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
}

/* DataTable supplies the measured sticky-band bottom through --data-table-head-top. */
@utility top-data-table-head {
  top: var(--data-table-head-top, 0px);
}

/* Use a named utility because content-sized grid columns cannot be represented by spacing tokens. */
@utility grid-cols-term {
  grid-template-columns: auto 1fr;
}

/* Named grid utility for the list body's flexible content and fixed-width aside. */
@utility grid-cols-list-aside {
  grid-template-columns: minmax(0, 1fr) var(--spacing-list-aside);
}

/* Named grid utility for the fixed-width aside and 5:6 form panels. */
@utility grid-cols-form-page {
  grid-template-columns: var(--spacing-form-page-aside) minmax(0, 5fr) minmax(0, 6fr);
}

/* Named grid utility for settings navigation and its flexible body. */
@utility grid-cols-settings-page {
  grid-template-columns: var(--spacing-settings-nav) minmax(0, 1fr);
}

/* Named responsive history grid: thumbnail, text and remove, adding actions from lg. */
@utility grid-cols-history-row {
  grid-template-columns: var(--spacing-history-thumb-sm) minmax(0, 1fr) auto;
}

@utility grid-cols-history-row-wide {
  grid-template-columns: var(--spacing-history-thumb) minmax(0, 1fr) auto auto;
}

/*
 * Width is relative to the folder backplate; FolderArt supplies per-sheet positions and rotations
 * through style.
 */
@utility w-folder-preview {
  width: 68%;
}
